def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if v is None:
        sites = s.get('sites') or []
        n = sum(max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites)
        volume = (s.get('lattice') or {}).get('volume_A3')
        v = volume / n if volume is not None and n > 0 else 0.0
    return float(log1p(v)) if isfinite(v) and v > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    ep = s.get('element_properties') or {}
    total = 0.0
    covered = 0.0
    spheres = 0.0
    for t in sites:
        o = t.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        total += o
        p = ep.get(t.get('element')) or {}
        r = p.get('covalent_radius_A')
        if r is not None and isfinite(r) and r > 0:
            covered += o
            spheres += o * r ** 3
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None:
        v = s.get('volume_per_atom_A3')
        volume = v * total if v is not None else 0.0
    if not volume or not isfinite(volume) or volume <= 0 or covered <= 0:
        return 0.0
    return float(4.0 * pi * spheres * total / (3.0 * volume * covered))

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    ep = s.get('element_properties') or {}
    n = len(sites)
    radii = []
    occ = []
    for t in sites:
        p = ep.get(t.get('element')) or {}
        r = p.get('covalent_radius_A') or p.get('atomic_radius_A') or 1.4
        radii.append(r if isfinite(r) and r > 0 else 1.4)
        o = t.get('occupancy')
        occ.append(max(0.0, o if o is not None else 1.0))
    best = inf
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[i] > 0 and occ[j] > 0 and d is not None and isfinite(d) and d > 0:
            best = min(best, d / (radii[i] + radii[j]))
    return float(best) if isfinite(best) else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    ep = s.get('element_properties') or {}
    n = len(sites)
    radii = []
    occ = []
    for t in sites:
        p = ep.get(t.get('element')) or {}
        r = p.get('covalent_radius_A') or p.get('atomic_radius_A') or 1.4
        radii.append(r if isfinite(r) and r > 0 else 1.4)
        o = t.get('occupancy')
        occ.append(max(0.0, o if o is not None else 1.0))
    nearest = [inf] * n
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[j] > 0 and d is not None and isfinite(d) and d > 0:
            nearest[i] = min(nearest[i], d / (radii[i] + radii[j]))
    weight = sum(occ[i] for i in range(n) if isfinite(nearest[i]))
    return float(sum(occ[i] * nearest[i] for i in range(n) if isfinite(nearest[i])) / weight) if weight > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    elements = [t.get('element') for t in sites]
    nearest = [inf] * n
    counts = {}
    for i in range(n):
        counts[elements[i]] = counts.get(elements[i], 0.0) + occ[i]
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[j] > 0 and d is not None and isfinite(d) and d > 0:
            nearest[i] = min(nearest[i], d)
    unlike = 0.0
    weight = 0.0
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and isfinite(d) and d > 0 and isfinite(nearest[i]) and d <= 1.35 * nearest[i]:
            w = occ[i] * occ[j]
            weight += w
            if elements[i] != elements[j]:
                unlike += w
    total = sum(occ)
    if weight <= 0 or total <= 0:
        return 0.0
    expected = 1.0 - sum((v / total) ** 2 for v in counts.values())
    return float(unlike / weight - expected)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    ep = s.get('element_properties') or {}
    n = len(sites)
    occ = []
    radii = []
    chi = []
    for t in sites:
        p = ep.get(t.get('element')) or {}
        r = p.get('covalent_radius_A') or p.get('atomic_radius_A') or 1.4
        radii.append(r if isfinite(r) and r > 0 else 1.4)
        chi.append(p.get('eneg'))
        o = t.get('occupancy')
        occ.append(max(0.0, o if o is not None else 1.0))
    value = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and isfinite(d) and d > 0:
            if chi[i] is not None and chi[j] is not None and isfinite(chi[i]) and isfinite(chi[j]):
                x = d / (radii[i] + radii[j])
                if x < 2.0:
                    value += occ[i] * occ[j] * (chi[i] - chi[j]) ** 2 * exp(-x ** 6) / d
    total = sum(occ)
    return float(value / (2.0 * total)) if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    ep = s.get('element_properties') or {}
    total = 0.0
    covered = 0.0
    electrons = 0.0
    for t in s.get('sites') or []:
        o = t.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        total += o
        v = (ep.get(t.get('element')) or {}).get('valence_electrons')
        if v is not None and isfinite(v) and v >= 0:
            covered += o
            electrons += o * v
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None:
        vpa = s.get('volume_per_atom_A3')
        volume = vpa * total if vpa is not None else 0.0
    if covered <= 0 or volume is None or not isfinite(volume) or volume <= 0:
        return 0.0
    return float(electrons * total / (covered * volume))

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    ep = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    r = (ep.get('C') or {}).get('covalent_radius_A')
    r = r if r is not None and isfinite(r) and r > 0 else 0.76
    value = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and sites[i].get('element') == 'C' and sites[j].get('element') == 'C' and d is not None and isfinite(d) and d > 0:
            x = d / (2.4 * r)
            if x < 2.0:
                value += occ[i] * occ[j] * exp(-x ** 6)
    total = sum(occ)
    return float(value / (2.0 * total)) if total > 0 else 0.0

