def feature(s):
    if not s:
        return 0.0
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3 or any(len(row) != 3 for row in matrix):
        return 0.0
    a = np.asarray(matrix)
    if not np.all(np.isfinite(a)):
        return 0.0
    singular = np.linalg.svd(a, compute_uv=False)
    smallest = float(np.min(singular))
    largest = float(np.max(singular))
    return float(log(largest / smallest)) if smallest > 0 and isfinite(largest) else 0.0
